/-- `image f s` is the forward image of `s` under `f`. -/
def image (f : α → β) (s : Finset α) : Finset β :=
  (s.1.map f).toFinset

/-- The disjoint union of two `powersetCard`s. -/
def disjUnion : powersetCard α (m + n) :=
  ⟨s.val.disjUnion t hst, by rw [mem_iff, Finset.card_disjUnion, card_eq s, card_eq t]⟩

/-- Disjoint sum of finsets. -/
def disjSum : Finset (α ⊕ β) :=
  ⟨s.1.disjSum t.1, s.2.disjSum t.2⟩

/-- The finset of those partitions in which every part is used less than `m` times. -/
def countRestricted (n : ℕ) (m : ℕ) : Finset n.Partition :=
  Finset.univ.filter fun x ↦ ∀ i ∈ x.parts, x.parts.count i < m
